const API_BASE = 'http://localhost:4000/api';
const state = { page: 'dashboard', authMode: 'login', authError: '', authBusy: false, user: null, token: localStorage.getItem('studenthub_token'), myCourses: [], myResources: [], myAssignments: [], myTimetable: [], myNotifications: [], cbtAttempts: [], cbtSession: null, cbtIndex: 0, cbtAnswers: [], cbtResult: null, curriculumLevel: '100', curriculumSemester: 'First semester', cgpaRows: [] };
function svg(name){ return icons[name] || '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 12h14"/></svg>'; }
function userName(){ return state.user?.name || 'Student'; }
function userInitials(){ return userName().split(/\s+/).filter(Boolean).slice(0,2).map((part)=>part[0].toUpperCase()).join('') || 'S'; }
function profileAvatar(){ return state.user?.profilePicture ? `<img src="${state.user.profilePicture}" alt="${userName()} profile picture"/>` : userInitials(); }
function userCourse(){ return state.user?.course || 'Your programme'; }
function userLevel(){ return state.user?.level || 'Student'; }
function myCoursesPanel(){ return `<div class="card my-courses-panel"><div class="card-head"><div><span class="eyebrow">Your academic load</span><h2>My courses</h2></div><span class="tag teal">${state.myCourses.length} added</span></div><form id="my-course-form" class="course-form"><input name="code" class="field" placeholder="Code e.g. CPE 201" required/><input name="title" class="field" placeholder="Course title" required/><input name="units" class="field" type="number" min="1" max="12" placeholder="Units" required/><select name="semester" class="field" required><option value="">Semester</option><option>First semester</option><option>Second semester</option></select><select name="type" class="field" required><option value="">Course type</option><option>GET</option><option>GST</option><option>Departmental</option><option>Elective</option></select><button class="primary" type="submit">Add course</button></form>${state.myCourses.length?`<div class="my-course-list">${state.myCourses.map(course=>`<div class="my-course-row"><div><b>${course.code} · ${course.title}</b><small>${course.units} unit(s) · ${course.type} · ${course.semester}</small></div><button class="remove-course" data-course-remove="${course.id}" aria-label="Remove ${course.code}">×</button></div>`).join('')}</div>`:'<p class="empty-courses">Add the courses you are taking this semester. You can change this list whenever your registration changes.</p>'}</div>`; }
function myResourcesPanel(){ return `<div class="card my-courses-panel"><div class="card-head"><div><span class="eyebrow">Your personal library</span><h2>My resources</h2></div><span class="tag teal">${state.myResources.length} saved</span></div><form id="resource-form" class="resource-form"><input name="title" class="field" placeholder="Resource title" required/><input name="courseCode" class="field" placeholder="Course code e.g. CPE 201" required/><select name="type" class="field" required><option value="">Resource type</option><option>Note</option><option>PDF</option><option>Link</option><option>Video</option></select><input name="link" class="field" type="url" placeholder="Optional link (https://...)" /><label class="upload-field"><span>Choose a file</span><input name="file" type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.png,.jpg,.jpeg"/></label><button class="primary" type="submit">Save resource</button></form>${state.myResources.length?`<div class="my-course-list">${state.myResources.map(resource=>`<div class="my-course-row"><div><b>${resource.title}</b><small>${resource.courseCode} · ${resource.type}${resource.fileName?` · ${resource.fileName}`:resource.link?' · Linked resource':''}</small>${resource.fileUrl?`<a class="resource-open" href="${API_BASE.replace('/api','')}${resource.fileUrl}" target="_blank" rel="noopener noreferrer">Open file ↗</a>`:''}</div><button class="remove-course" data-resource-remove="${resource.id}" aria-label="Remove ${resource.title}">×</button></div>`).join('')}</div>`:'<p class="empty-courses">Save notes, links, videos, and study materials here. Your library starts with the resources you choose.</p>'}</div>`; }
function personalize(){ if(!state.user) return; const avatar=document.querySelector('.user .avatar'); const name=document.querySelector('.user b'); const meta=document.querySelector('.user small'); const greeting=document.querySelector('.page-title'); if(avatar) avatar.innerHTML=profileAvatar(); if(name) name.textContent=userName(); if(meta) meta.textContent=`${userCourse()} · ${userLevel()}`; if(state.page==='dashboard'){ if(greeting) greeting.textContent=`Good morning, ${userName().split(/\s+/)[0]}.`; const programmeStat=document.querySelector('.stats-grid .stat-card:nth-child(3) .stat-top span'); const programmeNumber=document.querySelector('.stats-grid .stat-card:nth-child(3) .stat-number'); const firstClass=document.querySelector('.class-row strong'); const firstClassMeta=document.querySelector('.class-row strong + br + span'); if(programmeStat) programmeStat.textContent='Your programme'; if(programmeNumber) programmeNumber.innerHTML='01 <small class="stat-delta">selected</small>'; if(firstClass) firstClass.innerHTML=`<i class="class-dot"></i>${userCourse()}`; if(firstClassMeta) firstClassMeta.textContent=`${userLevel()} · ${state.user.university || 'StudentHub'}`; } }
function layout(content){ return `<div class="shell"><aside class="sidebar"><div class="logo"><div class="logo-mark">S</div>Student<span>Hub</span></div><div class="nav-label">Workspace</div><nav class="nav">${nav.map(([id,label,icon])=>`<button class="${state.page===id?'active':''}" data-page="${id}">${svg(icon)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><span class="sidebar-kicker">Build your workspace</span><p>Add the courses and resources you are using so your dashboard stays accurate.</p><div class="sidebar-actions"><button data-page="courses">${svg('plus')}<span>Add a course</span></button><button data-page="notes">${svg('file')}<span>Save a resource</span></button></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" aria-label="Open menu">${svg('grid')}</button><div class="breadcrumb">Workspace <span>/</span> <strong>${nav.find(x=>x[0]===state.page)?.[1] || 'Dashboard'}</strong></div><div class="top-actions"><button class="icon-btn" title="Notifications" data-page="notifications">${svg('bell')}<i class="badge">3</i></button><div class="user"><div class="avatar">${profileAvatar()}</div><div><b>${userName()}</b><small>${userCourse()} · ${userLevel()}</small></div></div></div></header><section class="content">${content}</section><nav class="mobile-nav">${nav.slice(0,5).map(([id,label,icon])=>`<button class="${state.page===id?'active':''}" data-page="${id}">${svg(icon)}<span>${label.split(' ')[0]}</span></button>`).join('')}</nav></main></div>`; }
function dashboard(){ return `<div class="hero-row"><div><p class="eyebrow">Wednesday, September 25, 2026</p><h1 class="page-title">Good morning, Johnson.</h1><p class="subtle">Here is your academic pulse for today.</p></div><div class="date-pill">Fall semester · Week 8</div></div><div class="grid stats-grid"><div class="card stat-card" style="--accent:var(--teal);--soft:var(--teal-soft)"><div class="stat-top"><span>Current CGPA</span><div class="stat-icon">${svg('chart')}</div></div><div class="stat-number">4.21 <small class="stat-delta">↑ 0.18</small></div></div><div class="card stat-card" style="--accent:var(--coral);--soft:var(--coral-soft)"><div class="stat-top"><span>Pending tasks</span><div class="stat-icon">${svg('check')}</div></div><div class="stat-number">06 <small class="stat-delta" style="color:var(--coral)">2 due soon</small></div></div><div class="card stat-card" style="--accent:var(--blue);--soft:var(--blue-soft)"><div class="stat-top"><span>Enrolled courses</span><div class="stat-icon">${svg('book')}</div></div><div class="stat-number">08 <small class="stat-delta">this semester</small></div></div><div class="card stat-card" style="--accent:var(--yellow);--soft:var(--yellow-soft)"><div class="stat-top"><span>Study streak</span><div class="stat-icon">${svg('bolt')}</div></div><div class="stat-number">12 <small class="stat-delta" style="color:#ae7d11">days</small></div></div></div><div class="grid dashboard-grid"><div class="card"><div class="card-head"><h2>Upcoming classes</h2><button class="text-btn" data-page="timetable">View timetable →</button></div><div class="classes"><div class="class-row"><time>09:00<br/><b>10:30 AM</b></time><div><strong><i class="class-dot"></i>Data Structures</strong><br/><span>CSC 301 · Dr. A. Okafor</span></div><span class="room">LT 04</span></div><div class="class-row"><time>12:00<br/><b>01:30 PM</b></time><div><strong><i class="class-dot" style="background:var(--coral)"></i>Calculus III</strong><br/><span>MTH 204 · Prof. S. Bello</span></div><span class="room">Room B12</span></div><div class="class-row"><time>03:00<br/><b>04:00 PM</b></time><div><strong><i class="class-dot" style="background:var(--blue)"></i>Database Systems</strong><br/><span>CSC 305 · Dr. E. Adeyemi</span></div><span class="room">Lab 2</span></div></div></div><div class="card"><div class="card-head"><h2>Needs your attention</h2><button class="text-btn" data-page="assignments">See all</button></div><div class="assignment-list"><div class="assignment"><div class="assignment-title"><span>Database schema design</span><span class="tag coral">Due tomorrow</span></div><div class="assignment-meta"><span>CSC 305</span><b>65% complete</b></div></div><div class="assignment"><div class="assignment-title"><span>Problem set 4</span><span class="tag yellow">Due in 3 days</span></div><div class="assignment-meta"><span>MTH 204</span><b>Not started</b></div></div><div class="assignment"><div class="assignment-title"><span>Read chapter 7</span><span class="tag teal">Due Friday</span></div><div class="assignment-meta"><span>CSC 301</span><b>Completed</b></div></div></div></div><div class="card wide"><div class="card-head"><h2>Recent activity</h2><button class="text-btn">Mark all read</button></div><div class="activity-list"><div class="activity"><div class="activity-mark">${svg('file')}</div><p><b>New material uploaded</b> for Database Systems<small>Dr. E. Adeyemi · 42 minutes ago</small></p></div><div class="activity"><div class="activity-mark" style="background:var(--teal-soft);color:var(--teal)">${svg('check')}</div><p><b>Assignment graded</b> · Data Structures Quiz 2<small>You scored 18/20 · Yesterday</small></p></div></div></div></div>`; }
function dashboard(){ const hasCourses=state.myCourses.length>0; const totalUnits=state.myCourses.reduce((sum,course)=>sum+Number(course.units||0),0); const firstCourse=state.myCourses[0]; return `<div class="hero-row dashboard-welcome"><div><p class="eyebrow">Your academic workspace</p><h1 class="page-title">Good morning, ${userName().split(/\s+/)[0]}.</h1><p class="subtle">${hasCourses?'Your personal academic overview, built from the courses you added.':'Welcome to your new academic workspace. Start by adding the courses you are taking.'}</p></div><div class="date-pill">Fall semester · 2026</div></div>${!hasCourses?`<section class="card onboarding-card"><div class="onboarding-copy"><span class="welcome-icon">${svg('book')}</span><div><p class="eyebrow">Your dashboard is ready</p><h2>Add your courses to get started</h2><p>We will not guess your courses. Add your current courses and StudentHub will build your academic overview around them.</p><button class="primary" data-page="courses">Add my first course <span>→</span></button></div></div><div class="onboarding-steps"><div><b>01</b><span>Add courses</span><small>Enter your registered courses</small></div><div><b>02</b><span>Track your work</span><small>See assignments and notes</small></div><div><b>03</b><span>Stay on top</span><small>Build your semester rhythm</small></div></div></section>`:`<div class="grid stats-grid"><div class="card stat-card" style="--accent:var(--teal);--soft:var(--teal-soft)"><div class="stat-top"><span>Courses added</span><div class="stat-icon">${svg('book')}</div></div><div class="stat-number">${state.myCourses.length} <small class="stat-delta">this semester</small></div></div><div class="card stat-card" style="--accent:var(--blue);--soft:var(--blue-soft)"><div class="stat-top"><span>Total units</span><div class="stat-icon">${svg('chart')}</div></div><div class="stat-number">${totalUnits} <small class="stat-delta">registered</small></div></div><div class="card stat-card" style="--accent:var(--coral);--soft:var(--coral-soft)"><div class="stat-top"><span>Assignments</span><div class="stat-icon">${svg('check')}</div></div><div class="stat-number">— <small class="stat-delta" style="color:var(--muted)">add later</small></div></div><div class="card stat-card" style="--accent:var(--yellow);--soft:var(--yellow-soft)"><div class="stat-top"><span>Study streak</span><div class="stat-icon">${svg('bolt')}</div></div><div class="stat-number">0 <small class="stat-delta" style="color:#ae7d11">days</small></div></div></div><div class="card dashboard-course-card"><div class="card-head"><div><span class="eyebrow">Your registered courses</span><h2>Semester course load</h2></div><button class="text-btn" data-page="courses">Manage courses →</button></div><div class="dashboard-course-list">${state.myCourses.map(course=>`<div class="dashboard-course-row"><div class="course-avatar">${course.code.slice(0,2)}</div><div><b>${course.code} · ${course.title}</b><small>${course.type} · ${course.semester}</small></div><span class="unit-pill">${course.units} unit${course.units===1?'':'s'}</span></div>`).join('')}</div></div>`}<div class="grid dashboard-lower"><div class="card dashboard-empty-card"><div class="empty-icon">${svg('calendar')}</div><div><h2>Upcoming classes</h2><p>Your timetable will appear here once you add class times for your courses.</p><button class="text-btn" data-page="timetable">Open timetable →</button></div></div><div class="card dashboard-empty-card"><div class="empty-icon" style="background:var(--coral-soft);color:var(--coral)">${svg('check')}</div><div><h2>Assignments</h2><p>No assignments are connected yet. Your course list is the first step.</p><button class="text-btn" data-page="assignments">View assignments →</button></div></div></div><div class="card dashboard-tip"><div class="tip-mark">${svg('bolt')}</div><p><b>Build your workspace your way.</b><br/>StudentHub keeps your academic data personal. Add only the courses, classes, and tasks that apply to you.</p></div>`; }
function pageHeader(eyebrow,title,desc){ return `<div class="hero-row"><div><p class="eyebrow">${eyebrow}</p><h1 class="page-title">${title}</h1><p class="subtle">${desc}</p></div></div>`; }
function curriculumCourseRows(group){ return group.map(([code,title,units])=>`<tr><td><b>${code}</b></td><td>${title}</td><td>${units}</td><td><span class="tag teal">Core</span></td></tr>`).join(''); }
function computerEngineeringPage(){ const term=computerEngineeringCurriculum[state.curriculumLevel][state.curriculumSemester]; return `${pageHeader('Veritas University · Computer Engineering','Programme curriculum','NUC CCMAS benchmark planner for Engineering/Technology, with GST and departmental planning groups.')} ${myCoursesPanel()}<div class="curriculum-note"><b>Source status:</b> GET and CPE entries are benchmark planning subjects aligned to the NUC CCMAS Engineering/Technology discipline. GST entries are general-studies planning subjects. This is <b>not an official Veritas University course handbook</b>; confirm codes, units, prerequisites, and semester placement with Veritas before registration.</div><div class="toolbar curriculum-toolbar"><label>Level<select id="curriculum-level" class="filter">${Object.keys(computerEngineeringCurriculum).map(level=>`<option ${state.curriculumLevel===level?'selected':''} value="${level}">${level} Level</option>`).join('')}</select></label><div class="semester-tabs"><button class="${state.curriculumSemester==='First semester'?'active':''}" data-semester="First semester">First semester</button><button class="${state.curriculumSemester==='Second semester'?'active':''}" data-semester="Second semester">Second semester</button></div></div><div class="curriculum-summary"><div class="card"><span class="eyebrow">Programme</span><b>Computer Engineering</b><small>Veritas University, Abuja</small></div><div class="card"><span class="eyebrow">Benchmark</span><b>NUC CCMAS</b><small>Engineering / Technology</small></div><div class="card"><span class="eyebrow">Course groups</span><b>${term.get.length + term.gst.length + term.department.length} courses</b><small>GET + GST + departmental</small></div></div><div class="curriculum-grid"><div class="card curriculum-card"><div class="card-head"><div><span class="eyebrow">CCMAS benchmark group</span><h2>GET / supporting engineering</h2></div><span class="tag blue">GET</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Course</th><th>Units</th><th>Type</th></tr></thead><tbody>${curriculumCourseRows(term.get)}</tbody></table></div></div><div class="card curriculum-card"><div class="card-head"><div><span class="eyebrow">General studies planning group</span><h2>GST courses</h2></div><span class="tag yellow">GST</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Course</th><th>Units</th><th>Type</th></tr></thead><tbody>${curriculumCourseRows(term.gst)}</tbody></table></div></div><div class="card curriculum-card"><div class="card-head"><div><span class="eyebrow">CCMAS benchmark group</span><h2>Computer Engineering</h2></div><span class="tag teal">CPE</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Course</th><th>Units</th><th>Type</th></tr></thead><tbody>${curriculumCourseRows(term.department)}</tbody></table></div></div></div><div class="card curriculum-sources"><div class="card-head"><div><span class="eyebrow">Reference documents</span><h2>Verify before registration</h2></div></div><div class="source-list">${curriculumSources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label}<span>Open source ↗</span></a>`).join('')}</div></div>`; }
function coursesPage(){ return `${pageHeader('Your academic load','My courses','Add and manage the courses you are taking this semester.')} ${myCoursesPanel()}`; }
function notesPage(){ return `${pageHeader('Your personal library','Notes & resources','Save the materials you actually use. StudentHub will not invent resources for you.')} ${myResourcesPanel()}<div class="card resource-tip"><div class="tip-mark">${svg('file')}</div><p><b>Keep your study shelf focused.</b><br/>Add resources as you find them and connect each one to a course code so they stay easy to revisit.</p></div>`; }
function assignmentsPage(){ const pending=state.myAssignments.filter(item=>item.status!=='completed').length; const dueSoon=state.myAssignments.filter(item=>item.status!=='completed' && new Date(item.dueAt)-Date.now()<7*86400000).length; const rows=state.myAssignments.length?`<div class="assignment-list">${state.myAssignments.slice().sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt)).map(item=>{const status=item.status==='completed'?'Completed':item.status==='in-progress'?'In progress':'Not started'; return `<div class="assignment-card"><div class="assignment-card-main"><div class="assignment-file">${svg('check')}</div><div><h3>${item.title}</h3><p>${item.courseCode} · ${item.points} points</p></div></div><div class="assignment-card-meta"><div><span>Due date</span><b>${new Date(item.dueAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</b></div><span class="tag ${status==='Completed'?'teal':status==='In progress'?'yellow':'coral'}">${status}</span><select class="assignment-status field" data-assignment-status="${item.id}" aria-label="Update ${item.title} status"><option value="pending" ${item.status==='pending'?'selected':''}>Not started</option><option value="in-progress" ${item.status==='in-progress'?'selected':''}>In progress</option><option value="completed" ${item.status==='completed'?'selected':''}>Completed</option></select><button class="remove-course" data-assignment-remove="${item.id}" aria-label="Remove ${item.title}">×</button></div></div>`}).join('')}</div>`:`<div class="assignment-empty"><div class="empty-icon">${svg('check')}</div><div><span class="eyebrow">Your task list</span><h2>No assignments yet</h2><p>Add assignments as they are given to you. StudentHub will keep the due dates and progress in one place.</p></div></div>`; return `${pageHeader('Stay ahead of deadlines','Assignments','Capture your real coursework, track progress, and keep every deadline visible.')}<div class="assignment-summary"><div><span>Open tasks</span><b>${pending}</b></div><div><span>Due soon</span><b>${dueSoon}</b></div><div><span>Total assignments</span><b>${state.myAssignments.length}</b></div></div><div class="assignment-layout"><section class="card assignment-add"><div class="card-head"><div><span class="eyebrow">Add coursework</span><h2>New assignment</h2></div></div><form id="assignment-form"><input name="title" class="field" placeholder="Assignment title" required/><input name="courseCode" class="field" placeholder="Course code e.g. CPE 201" required/><div class="assignment-form-row"><label>Due date<input name="dueAt" class="field" type="date" required/></label><label>Points<input name="points" class="field" type="number" min="1" max="1000" placeholder="20" required/></label></div><button class="primary" type="submit">Add assignment <span>→</span></button></form></section><section class="card assignment-list-card"><div class="card-head"><div><span class="eyebrow">Your workload</span><h2>Assignment tracker</h2></div><span class="history-count">${state.myAssignments.length}</span></div>${rows}</section></div>`; }
function timetablePage(){ const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']; const entries=state.myTimetable.slice().sort((a,b)=>a.start.localeCompare(b.start)); const cells=days.map(day=>`<div class="schedule-day"><div class="schedule-day-head">${day}<span>${entries.filter(item=>item.day===day).length}</span></div><div class="schedule-day-list">${entries.filter(item=>item.day===day).map(item=>`<div class="schedule-entry"><div class="schedule-time">${item.start} — ${item.end}</div><b>${item.courseCode}</b>${item.room?`<small>${item.room}</small>`:''}<button class="schedule-remove" data-timetable-remove="${item.id}" aria-label="Remove ${item.courseCode}">×</button></div>`).join('')||'<div class="schedule-empty">No classes</div>'}</div></div>`).join(''); return `${pageHeader('Own your week','Timetable','Add your real class times and keep your week easy to scan.')}<div class="timetable-layout"><section class="card timetable-add"><div class="card-head"><div><span class="eyebrow">Build your week</span><h2>Add a class</h2></div></div><form id="timetable-form"><input name="courseCode" class="field" placeholder="Course code e.g. CPE 201" required/><select name="day" class="field" required><option value="">Choose day</option>${days.map(day=>`<option>${day}</option>`).join('')}</select><div class="time-row"><label>Starts<input name="start" class="field" type="time" required/></label><label>Ends<input name="end" class="field" type="time" required/></label></div><input name="room" class="field" placeholder="Room or location (optional)"/><button class="primary" type="submit">Add to timetable <span>→</span></button></form></section><section class="card timetable-board"><div class="card-head"><div><span class="eyebrow">Weekly schedule</span><h2>My timetable</h2></div><span class="history-count">${state.myTimetable.length}</span></div>${state.myTimetable.length?`<div class="schedule-grid">${cells}</div>`:`<div class="timetable-empty"><div class="empty-icon">${svg('calendar')}</div><div><span class="eyebrow">Your week starts here</span><h2>No classes added yet</h2><p>Add your class days and times to create a timetable that matches your semester.</p></div></div>`}</section></div>`; }
function cgpaPage(){ const points={A:5,B:4,C:3,D:2,E:1,F:0}; const total=state.cgpaRows.reduce((a,r)=>a+Number(r[1]||0),0); const weighted=state.cgpaRows.reduce((a,r)=>a+Number(r[1]||0)*(points[r[2]]||0),0); const gpa=total?(weighted/total).toFixed(2):'0.00'; const rows=state.cgpaRows.length?state.cgpaRows.map((r,i)=>`<div class="cgpa-row"><input class="field cg-course" value="${r[0]}" placeholder="Course code e.g. CPE 201"/><input class="field cg-unit" value="${r[1]}" type="number" min="1" max="12" placeholder="Units"/><select class="field cg-grade">${['A','B','C','D','E','F'].map(g=>`<option ${r[2]===g?'selected':''}>${g}</option>`).join('')}</select><button class="remove" data-remove="${i}" aria-label="Remove course">×</button></div>`).join(''):`<div class="cgpa-empty"><div class="empty-icon">${svg('chart')}</div><b>No courses entered yet</b><span>Add the courses and grades you want to calculate.</span></div>`; return `${pageHeader('Understand your results','CGPA calculator','Calculate your semester GPA using the Nigerian 5.0 grading scale.')}<div class="cgpa-intro"><div><span class="eyebrow">Your academic scorecard</span><h2>Every grade, clearly accounted for.</h2><p>Enter only the courses you want to include. Your calculation stays on this device.</p></div><div class="cgpa-scale"><b>5.0</b><span>maximum scale</span></div></div><div class="cgpa-layout"><section class="card cgpa-entry"><div class="card-head"><div><span class="eyebrow">Grade entries</span><h2>Semester courses</h2></div><button class="text-btn" id="add-row">+ Add course</button></div><div class="cgpa-labels"><span>Course code</span><span>Units</span><span>Grade</span><span></span></div><div id="cgpa-rows">${rows}</div><button class="primary cgpa-calculate" id="calculate">Calculate GPA <span>→</span></button></section><aside class="cgpa-result"><span class="eyebrow">Projected semester GPA</span><div class="big-score">${gpa}</div><p>${state.cgpaRows.length?`Based on ${state.cgpaRows.length} course${state.cgpaRows.length===1?'':'s'} entered above.`:'Add courses to see your GPA.'}</p><div class="result-grid"><div><span>Total units</span><b>${total}</b></div><div><span>Grade points</span><b>${weighted}</b></div></div><div class="grade-key"><span><b>A</b> 5 points</span><span><b>B</b> 4 points</span><span><b>C</b> 3 points</span><span><b>D</b> 2 points</span><span><b>E</b> 1 point</span><span><b>F</b> 0 points</span></div></aside></div>`; }
function profilePage(){ const user=state.user||{}; const preferences=user.preferences||{pushNotifications:true,weeklySummary:true}; return `${pageHeader('Your account','Profile & settings','Keep your student identity and preferences up to date.')}<div class="profile-layout"><section class="card profile-card"><div class="profile-cover"><span>StudentHub account</span><b>Academic workspace</b></div><div class="profile-head"><div class="profile-avatar-wrap"><div class="profile-large">${profileAvatar()}</div><label class="avatar-upload" title="Add profile picture"><input id="profile-picture" name="profilePicture" form="profile-form" type="file" accept="image/png,image/jpeg,image/webp"/><span>${svg('plus')}</span></label></div><div class="profile-identity"><h2>${user.name||'Student'}</h2><p>${user.email||'No email available'}</p><span class="profile-status"><i></i> Account active</span></div><button class="filter" data-logout>Log out</button></div><div class="profile-section-label">Personal information</div><form id="profile-form" class="profile-form"><div class="profile-form-grid"><label>Full name<input name="name" class="field" value="${user.name||''}" required/></label><label>Email address<input class="field" value="${user.email||''}" disabled/></label><label>University<input name="university" class="field" value="${user.university||''}"/></label><label>Programme<input name="course" class="field" value="${user.course||''}"/></label><label>Level<select name="level" class="field">${[100,200,300,400,500,600].map(level=>`<option ${String(user.level||'')===`${level} Level`?'selected':''}>${level} Level</option>`).join('')}</select></label><label>Matric number<input name="matricNumber" class="field" value="${user.matricNumber||''}"/></label></div><p class="avatar-help">Add a JPG, PNG, or WebP image up to 2 MB. Your initials will show when no picture is selected.</p><button class="primary" type="submit">Save profile <span>→</span></button></form></section><aside class="card preferences-card"><div class="preferences-heading"><span class="preference-icon">${svg('bell')}</span><div><span class="eyebrow">Your preferences</span><h2>Stay in control</h2><p>Choose how StudentHub keeps you informed.</p></div></div><div class="settings"><div class="setting preference-row"><div><b>Push notifications</b><small>Deadlines, grades, and course updates</small></div><button class="toggle ${preferences.pushNotifications?'active':''}" data-preference="pushNotifications" aria-pressed="${Boolean(preferences.pushNotifications)}"><i></i></button></div><div class="setting preference-row"><div><b>Weekly study summary</b><small>Receive a short progress report every Sunday</small></div><button class="toggle ${preferences.weeklySummary?'active':''}" data-preference="weeklySummary" aria-pressed="${Boolean(preferences.weeklySummary)}"><i></i></button></div></div><div class="profile-note">${svg('check')} Your profile changes are saved to your StudentHub account.</div></aside></div>`; }
function notificationsPage(){ const unread=state.myNotifications.filter(item=>!item.read).length; const rows=state.myNotifications.length?`<div class="notification-list">${state.myNotifications.slice().reverse().map(item=>`<div class="notification-row ${item.read?'':'unread'}"><div class="notification-mark">${svg(item.type==='resource'?'file':item.type==='assignment'?'check':'bell')}</div><div class="notification-copy"><b>${item.title}</b><p>${item.body}</p><small>${new Date(item.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</small></div>${item.read?'<span class="notification-seen">Read</span>':`<button class="notification-read" data-notification-read="${item.id}">Mark read</button>`}</div>`).join('')}</div>`:`<div class="notification-empty"><div class="empty-icon">${svg('bell')}</div><div><span class="eyebrow">You are all caught up</span><h2>No notifications yet</h2><p>Updates about your assignments, resources, and practice activity will appear here.</p></div></div>`; return `${pageHeader('Only what matters','Notifications','Keep track of important updates without the noise.')}<div class="notification-summary"><div><span>Unread</span><b>${unread}</b></div><div><span>Total updates</span><b>${state.myNotifications.length}</b></div><button class="filter" data-notifications-read-all ${unread?'':'disabled'}>Mark all as read</button></div><section class="card notification-card"><div class="card-head"><div><span class="eyebrow">Your inbox</span><h2>Recent updates</h2></div><span class="history-count">${unread}</span></div>${rows}</section>`; }
function cbtPage(){
  if(state.cbtSession) return cbtSessionPage();
  const hasCourses=state.myCourses.length>0;
  const courseOptions=state.myCourses.map(course=>`<option>${course.code}</option>`).join('');
  const result=state.cbtResult ? `<div class="cbt-result card"><div class="result-check">✓</div><div><span class="eyebrow">Practice complete</span><h2>${state.cbtResult.percentage}% score</h2><p>You answered ${state.cbtResult.score} of ${state.cbtResult.total} questions correctly.</p></div><button class="filter" data-cbt-dismiss>Close</button></div>` : '';
  const history=state.cbtAttempts.length ? `<div class="attempt-list">${state.cbtAttempts.slice().reverse().map(attempt=>`<div class="attempt-row"><div class="attempt-score">${attempt.percentage ?? Math.round((attempt.score/attempt.total)*100)}%</div><div><b>${attempt.score} of ${attempt.total} correct</b><small>${new Date(attempt.createdAt).toLocaleDateString()}</small></div></div>`).join('')}</div>` : `<div class="cbt-history-empty"><div class="history-icon">${svg('bolt')}</div><b>No attempts yet</b><span>Your completed practice sessions will appear here.</span></div>`;
  const body=hasCourses ? `<div class="cbt-layout"><section class="card cbt-setup"><div class="setup-intro"><span class="setup-number">01</span><div><span class="eyebrow">Start a session</span><h2>Choose your practice</h2><p>Use your own course list to build a focused revision session.</p></div></div><form id="cbt-start-form"><label>Course<select name="courseCode" class="field">${courseOptions}</select></label><label>Session length<select name="count" class="field"><option value="3">3 questions · Quick practice</option></select></label><div class="setup-note">${svg('check')} Results are calculated securely after submission.</div><button class="primary cbt-start-button" type="submit">Begin practice <span>→</span></button></form></section><section class="card cbt-history"><div class="card-head"><div><span class="eyebrow">Keep improving</span><h2>Recent attempts</h2></div><span class="history-count">${state.cbtAttempts.length}</span></div>${history}</section></div>` : `<div class="card cbt-empty"><div class="empty-icon">${svg('book')}</div><div><span class="eyebrow">Your practice library</span><h2>Add a course to begin</h2><p>CBT sessions use the courses you add to your workspace. Add at least one course to unlock practice.</p><button class="primary" data-page="courses">Add a course <span>→</span></button></div></div>`;
  return `${pageHeader('Test your understanding','CBT practice','Short, focused practice sessions to help you revise with confidence.')}<div class="cbt-overview"><div><span class="eyebrow">Practice center</span><h2>Learn it. Test it. Own it.</h2><p>Work through questions at your pace and get an instant score when you finish.</p></div><div class="cbt-overview-stat"><b>${state.cbtAttempts.length}</b><span>sessions completed</span></div></div>${result}${body}`;
}
function cbtSessionPage(){
  const question=state.cbtSession[state.cbtIndex];
  const selected=state.cbtAnswers[state.cbtIndex];
  const isLast=state.cbtIndex===state.cbtSession.length-1;
  const answered=state.cbtAnswers.filter(answer=>answer!==undefined).length;
  return `<div class="cbt-exam"><div class="cbt-exam-top"><button class="cbt-exit" data-page="cbt">← Exit practice</button><div class="cbt-exam-brand"><span class="logo-mark">S</span><b>Student<span>Hub</span></b></div><div class="cbt-exam-count">${answered}/${state.cbtSession.length} answered</div></div><div class="cbt-exam-layout"><aside class="cbt-question-nav"><span class="eyebrow">Your session</span><h2>Question map</h2><p>Move through the questions and review your choices before submitting.</p><div class="question-map">${state.cbtSession.map((_,index)=>`<button class="${index===state.cbtIndex?'active ':''}${state.cbtAnswers[index]!==undefined?'answered':''}" data-cbt-jump="${index}">${String(index+1).padStart(2,'0')}</button>`).join('')}</div><div class="cbt-legend"><span><i class="current"></i>Current</span><span><i class="done"></i>Answered</span></div></aside><main class="cbt-question-card"><div class="question-topline"><span>Question ${String(state.cbtIndex+1).padStart(2,'0')}</span><span>${state.cbtSession.length} questions</span></div><div class="cbt-progress"><span style="width:${((state.cbtIndex+1)/state.cbtSession.length)*100}%"></span></div><p class="question-label">Select one answer</p><h1>${question.prompt}</h1><div class="answer-list">${question.options.map((option,index)=>`<button class="answer-option ${selected===index?'selected':''}" data-answer="${index}"><span class="answer-letter">${String.fromCharCode(65+index)}</span><span>${option}</span><span class="answer-radio"></span></button>`).join('')}</div><div class="session-actions">${state.cbtIndex?'<button class="filter" data-cbt-prev>← Previous</button>':'<span></span>'}<button class="primary" data-cbt-next>${isLast?'Submit answers':'Next question →'}</button></div></main></div></div>`;
}
function authScreen(){ const isLogin=state.authMode==='login'; const selectedUniversity=state.signupUniversity||universities[0]; const coursesForUniversity=universityCourses[selectedUniversity]; return `<main class="auth-shell"><section class="auth-visual"><div class="logo"><div class="logo-mark">S</div>Student<span>Hub</span></div><div class="auth-hero"><p class="eyebrow">Your academic command center</p><h1>Make every semester<br/><em>count.</em></h1><p>One focused workspace for courses, assignments, notes, practice, and your next big academic win.</p><div class="auth-points"><span>✓ Stay ahead of deadlines</span><span>✓ Track your progress</span><span>✓ Study with confidence</span></div></div><small class="auth-footer">Built for students who are going places.</small></section><section class="auth-panel"><div class="auth-card"><div class="auth-mobile-logo"><div class="logo-mark">S</div>Student<span>Hub</span></div><div class="auth-heading"><p class="eyebrow">${isLogin?'Welcome back':'Create your account'}</p><h2>${isLogin?'Good to see you again.':'Start your StudentHub journey.'}</h2><p>${isLogin?'Sign in to continue to your academic workspace.':'Join your focused academic workspace in less than a minute.'}</p></div><div class="auth-tabs"><button class="${isLogin?'active':''}" data-auth-mode="login">Log in</button><button class="${!isLogin?'active':''}" data-auth-mode="signup">Sign up</button></div><form id="auth-form"><label>Email address<input name="email" type="email" placeholder="you@example.com" required autocomplete="email"/></label>${!isLogin?`<label>Full name<input name="name" type="text" placeholder="Johnson Doe" required autocomplete="name"/></label>`:''}<label>Password<input name="password" type="password" placeholder="At least 8 characters" required minlength="8" autocomplete="${isLogin?'current-password':'new-password'}"/></label>${!isLogin?`<label>University<select name="university" id="university-select" required>${universities.map(university=>`<option ${university===selectedUniversity?'selected':''}>${university}</option>`).join('')}</select></label><label>Course / programme<select name="course" id="course-select" required>${coursesForUniversity.map(course=>`<option>${course}</option>`).join('')}</select></label><div class="auth-two"><label>Level<select name="level" required><option value="">Select level</option>${[100,200,300,400,500,600].map(level=>`<option>${level} Level</option>`).join('')}</select></label><label>University location<input value="${selectedUniversity==='Veritas University, Abuja'?'Abuja, FCT':'Nigeria'}" readonly/></label></div>`:''}${state.authError?`<div class="auth-error">${state.authError}</div>`:''}<button class="primary auth-submit" type="submit">${state.authBusy?'Please wait...':isLogin?'Log in to StudentHub':'Create my account'} <span>→</span></button></form><p class="auth-legal">By continuing, you agree to StudentHub's terms and privacy policy.</p></div></section></main>`; }
function render(){ if(!state.token){document.getElementById('app').innerHTML=authScreen();bind();return;} const views={dashboard,courses:coursesPage,notes:notesPage,cbt:cbtPage,assignments:assignmentsPage,timetable:timetablePage,cgpa:cgpaPage,notifications:notificationsPage,profile:profilePage}; document.getElementById('app').innerHTML=layout(`<div class="section-page">${(views[state.page]||dashboard)()}</div>`); bind(); personalize(); }
function bind(){
  document.querySelectorAll('[data-auth-mode]').forEach(el=>el.addEventListener('click',()=>{state.authMode=el.dataset.authMode;state.authError='';render();}));
  const universitySelect=document.getElementById('university-select'); if(universitySelect) universitySelect.onchange=()=>{state.signupUniversity=universitySelect.value;render()};
  const authForm=document.getElementById('auth-form'); if(authForm) authForm.onsubmit=submitAuth;
  document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{state.page=el.dataset.page;render()}));
  document.querySelectorAll('[data-semester]').forEach(el=>el.addEventListener('click',()=>{state.curriculumSemester=el.dataset.semester;render()}));
  const curriculumLevel=document.getElementById('curriculum-level'); if(curriculumLevel) curriculumLevel.onchange=()=>{state.curriculumLevel=curriculumLevel.value;render()};
  const courseForm=document.getElementById('my-course-form'); if(courseForm) courseForm.onsubmit=addMyCourse;
  document.querySelectorAll('[data-course-remove]').forEach(el=>el.onclick=()=>removeMyCourse(el.dataset.courseRemove));
  const resourceForm=document.getElementById('resource-form'); if(resourceForm) resourceForm.onsubmit=addMyResource;
  document.querySelectorAll('[data-resource-remove]').forEach(el=>el.onclick=()=>removeMyResource(el.dataset.resourceRemove));
  const assignmentForm=document.getElementById('assignment-form'); if(assignmentForm) assignmentForm.onsubmit=addMyAssignment;
  document.querySelectorAll('[data-assignment-remove]').forEach(el=>el.onclick=()=>removeMyAssignment(el.dataset.assignmentRemove));
  document.querySelectorAll('[data-assignment-status]').forEach(el=>el.onchange=()=>updateMyAssignment(el.dataset.assignmentStatus,el.value));
  const timetableForm=document.getElementById('timetable-form'); if(timetableForm) timetableForm.onsubmit=addMyTimetable;
  document.querySelectorAll('[data-timetable-remove]').forEach(el=>el.onclick=()=>removeMyTimetable(el.dataset.timetableRemove));
  document.querySelectorAll('[data-notification-read]').forEach(el=>el.onclick=()=>markNotificationRead(el.dataset.notificationRead));
  const markAll=document.querySelector('[data-notifications-read-all]'); if(markAll) markAll.onclick=markAllNotificationsRead;
  const profileForm=document.getElementById('profile-form'); if(profileForm) profileForm.onsubmit=saveProfile;
  const profilePicture=document.getElementById('profile-picture'); if(profilePicture) profilePicture.onchange=previewProfilePicture;
  document.querySelectorAll('[data-preference]').forEach(el=>el.onclick=()=>togglePreference(el.dataset.preference));
  const logout=document.querySelector('[data-logout]'); if(logout) logout.onclick=logoutUser;
  const cbtStart=document.getElementById('cbt-start-form'); if(cbtStart) cbtStart.onsubmit=startCbt;
  document.querySelectorAll('[data-answer]').forEach(el=>el.onclick=()=>{state.cbtAnswers[state.cbtIndex]=Number(el.dataset.answer);render()});
  document.querySelectorAll('[data-cbt-jump]').forEach(el=>el.onclick=()=>{state.cbtIndex=Number(el.dataset.cbtJump);render()});
  document.querySelectorAll('[data-cbt-dismiss]').forEach(el=>el.onclick=()=>{state.cbtResult=null;render()});
  const cbtNext=document.querySelector('[data-cbt-next]'); if(cbtNext) cbtNext.onclick=nextCbtQuestion;
  const cbtPrev=document.querySelector('[data-cbt-prev]'); if(cbtPrev) cbtPrev.onclick=()=>{state.cbtIndex-=1;render()};
  document.querySelectorAll('[data-alert]').forEach(el=>el.addEventListener('click',()=>alert(el.dataset.alert)));
  const add=document.getElementById('add-row'); if(add) add.onclick=()=>{state.cgpaRows.push(['NEW 000','3','A']);render()};
  document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{state.cgpaRows.splice(Number(el.dataset.remove),1);render()});
  const calc=document.getElementById('calculate'); if(calc) calc.onclick=()=>{document.querySelectorAll('#cgpa-rows .form-row').forEach((row,i)=>{state.cgpaRows[i]=[row.querySelector('.cg-course').value,row.querySelector('.cg-unit').value,row.querySelector('.cg-grade').value]});render()};
}
async function loadMyCourses(){ const response=await fetch(`${API_BASE}/my-courses`,{headers:{Authorization:`Bearer ${state.token}`}}); if(!response.ok) throw new Error('Unable to load your courses.'); const result=await response.json(); state.myCourses=result.courses||[]; }
async function loadMyResources(){ const response=await fetch(`${API_BASE}/my-resources`,{headers:{Authorization:`Bearer ${state.token}`}}); if(!response.ok) throw new Error('Unable to load your resources.'); const result=await response.json(); state.myResources=result.resources||[]; }
async function addMyCourse(event){ event.preventDefault(); const payload=Object.fromEntries(new FormData(event.target).entries()); try{const response=await fetch(`${API_BASE}/my-courses`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to add course.');state.myCourses.push(result.course);render();}catch(error){alert(error.message);} }
async function removeMyCourse(id){ try{const response=await fetch(`${API_BASE}/my-courses/${id}`,{method:'DELETE',headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){const result=await response.json();throw new Error(result.error||'Unable to remove course.');}state.myCourses=state.myCourses.filter(course=>course.id!==id);render();}catch(error){alert(error.message);} }
async function addMyResource(event){ event.preventDefault(); const form=new FormData(event.target); const file=form.get('file'); const payload={title:form.get('title'),courseCode:form.get('courseCode'),type:form.get('type'),link:form.get('link')}; let endpoint='/my-resources'; if(file && file.size){ if(file.size>10*1024*1024){alert('Files must be smaller than 10 MB.');return;} payload.fileName=file.name;payload.fileData=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);}); endpoint='/my-resources/upload'; } try{const response=await fetch(`${API_BASE}${endpoint}`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to save resource.');state.myResources.push(result.resource);render();}catch(error){alert(error.message);} }
async function removeMyResource(id){ try{const response=await fetch(`${API_BASE}/my-resources/${id}`,{method:'DELETE',headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){const result=await response.json();throw new Error(result.error||'Unable to remove resource.');}state.myResources=state.myResources.filter(resource=>resource.id!==id);render();}catch(error){alert(error.message);} }
async function loadMyAssignments(){ const response=await fetch(`${API_BASE}/my-assignments`,{headers:{Authorization:`Bearer ${state.token}`}}); if(!response.ok) throw new Error('Unable to load your assignments.'); const result=await response.json(); state.myAssignments=result.assignments||[]; }
async function addMyAssignment(event){ event.preventDefault(); const payload=Object.fromEntries(new FormData(event.target).entries()); try{const response=await fetch(`${API_BASE}/my-assignments`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to add assignment.');state.myAssignments.push(result.assignment);render();}catch(error){alert(error.message);} }
async function updateMyAssignment(id,status){ try{const response=await fetch(`${API_BASE}/my-assignments/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify({status})});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to update assignment.');const index=state.myAssignments.findIndex(item=>item.id===id);if(index>=0) state.myAssignments[index]=result.assignment;render();}catch(error){alert(error.message);} }
async function removeMyAssignment(id){ try{const response=await fetch(`${API_BASE}/my-assignments/${id}`,{method:'DELETE',headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok) throw new Error('Unable to remove assignment.');state.myAssignments=state.myAssignments.filter(item=>item.id!==id);render();}catch(error){alert(error.message);} }
async function loadMyTimetable(){ const response=await fetch(`${API_BASE}/my-timetable`,{headers:{Authorization:`Bearer ${state.token}`}}); if(!response.ok) throw new Error('Unable to load your timetable.'); const result=await response.json(); state.myTimetable=result.timetable||[]; }
async function addMyTimetable(event){ event.preventDefault(); const payload=Object.fromEntries(new FormData(event.target).entries()); try{const response=await fetch(`${API_BASE}/my-timetable`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to add timetable entry.');state.myTimetable.push(result.entry);render();}catch(error){alert(error.message);} }
async function removeMyTimetable(id){ try{const response=await fetch(`${API_BASE}/my-timetable/${id}`,{method:'DELETE',headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok) throw new Error('Unable to remove timetable entry.');state.myTimetable=state.myTimetable.filter(item=>item.id!==id);render();}catch(error){alert(error.message);} }
async function loadMyNotifications(){ const response=await fetch(`${API_BASE}/my-notifications`,{headers:{Authorization:`Bearer ${state.token}`}}); if(!response.ok) throw new Error('Unable to load your notifications.'); const result=await response.json(); state.myNotifications=result.notifications||[]; }
async function markNotificationRead(id){ try{const response=await fetch(`${API_BASE}/my-notifications/${id}`,{method:'PATCH',headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok) throw new Error('Unable to update notification.');const index=state.myNotifications.findIndex(item=>item.id===id);if(index>=0) state.myNotifications[index].read=true;render();}catch(error){alert(error.message);} }
async function markAllNotificationsRead(){ try{const response=await fetch(`${API_BASE}/my-notifications/read-all`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok) throw new Error('Unable to update notifications.');state.myNotifications.forEach(item=>{item.read=true});render();}catch(error){alert(error.message);} }
async function previewProfilePicture(event){ const file=event.target.files?.[0]; if(!file) return; if(!['image/png','image/jpeg','image/webp'].includes(file.type)){alert('Choose a PNG, JPG, or WebP image.');event.target.value='';return;} if(file.size>2*1024*1024){alert('Profile pictures must be smaller than 2 MB.');event.target.value='';return;} const reader=new FileReader(); reader.onload=()=>{const image=document.querySelector('.profile-large');if(image) image.innerHTML=`<img src="${reader.result}" alt="Profile picture preview"/>`;}; reader.readAsDataURL(file); }
async function saveProfile(event){ event.preventDefault(); const form=new FormData(event.target); const payload={name:form.get('name'),university:form.get('university'),course:form.get('course'),level:form.get('level'),matricNumber:form.get('matricNumber')}; const file=form.get('profilePicture'); try{if(file && file.size){if(!['image/png','image/jpeg','image/webp'].includes(file.type)) throw new Error('Choose a PNG, JPG, or WebP image.');if(file.size>2*1024*1024) throw new Error('Profile pictures must be smaller than 2 MB.');payload.profilePicture=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});} const response=await fetch(`${API_BASE}/profile`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to save profile.');state.user=result.user;render();}catch(error){alert(error.message);} }
async function togglePreference(preference){ const current=state.user?.preferences||{pushNotifications:true,weeklySummary:true}; const preferences={...current,[preference]:!current[preference]}; try{const response=await fetch(`${API_BASE}/profile`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify({preferences})});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to update preference.');state.user=result.user;render();}catch(error){alert(error.message);} }
async function logoutUser(){ try{await fetch(`${API_BASE}/auth/logout`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`}});}finally{localStorage.removeItem('studenthub_token');state.token=null;state.user=null;state.myCourses=[];state.myResources=[];state.myAssignments=[];state.myTimetable=[];state.myNotifications=[];state.cbtAttempts=[];state.page='dashboard';render();} }
async function loadCbtAttempts(){ const response=await fetch(`${API_BASE}/cbt/attempts`,{headers:{Authorization:`Bearer ${state.token}`}}); if(!response.ok) throw new Error('Unable to load CBT attempts.'); const result=await response.json(); state.cbtAttempts=result.attempts||[]; }
async function startCbt(event){ event.preventDefault(); try{const response=await fetch(`${API_BASE}/cbt/questions`,{headers:{Authorization:`Bearer ${state.token}`}});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to start practice.');state.cbtSession=result.questions;state.cbtIndex=0;state.cbtAnswers=[];state.cbtResult=null;render();}catch(error){alert(error.message);} }
async function nextCbtQuestion(){ if(state.cbtAnswers[state.cbtIndex]===undefined){alert('Choose an answer before continuing.');return;} if(state.cbtIndex<state.cbtSession.length-1){state.cbtIndex+=1;render();return;} try{const response=await fetch(`${API_BASE}/cbt/submit`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.token}`},body:JSON.stringify({answers:state.cbtAnswers})});const result=await response.json();if(!response.ok) throw new Error(result.error||'Unable to submit practice.');state.cbtAttempts.push(result.attempt);state.cbtSession=null;state.cbtIndex=0;state.cbtAnswers=[];state.cbtResult=result.attempt;render();}catch(error){alert(error.message);} }
async function submitAuth(event){ event.preventDefault(); state.authBusy=true;state.authError='';render(); const form=new FormData(event.target); const payload=Object.fromEntries(form.entries()); const endpoint=state.authMode==='login'?'/auth/login':'/auth/register'; try{const response=await fetch(API_BASE+endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok) throw new Error(result.error||'Authentication failed.');if(state.authMode==='signup'){state.authMode='login';state.authError='Account created. Please log in to continue.';state.authBusy=false;render();return;} localStorage.setItem('studenthub_token',result.token);state.token=result.token;state.user=result.user;await loadMyCourses();await loadMyResources();await loadMyAssignments();await loadMyTimetable();await loadMyNotifications();state.authBusy=false;render();}catch(error){state.authBusy=false;state.authError=error.message.includes('Failed to fetch')?'The API is offline. Start it with: node backend/server.js':error.message;render();} }
async function restoreSession(){ if(!state.token){render();return;} try{const response=await fetch(`${API_BASE}/users/me`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok) throw new Error('Session expired.');const result=await response.json();state.user=result.user;await loadMyCourses();await loadMyResources();await loadMyAssignments();await loadMyTimetable();await loadMyNotifications();await loadCbtAttempts();const profileLevel=String(result.user.level||'').match(/\d+/)?.[0];if(profileLevel && computerEngineeringCurriculum[profileLevel]) state.curriculumLevel=profileLevel;render();}catch(error){localStorage.removeItem('studenthub_token');state.token=null;state.user=null;state.myCourses=[];state.myResources=[];state.myAssignments=[];state.myTimetable=[];state.myNotifications=[];state.cbtAttempts=[];render();} }
restoreSession();
